package com.handy.parakeet; import android.app.*; import android.os.*; import android.content.*; import android.net.*; import android.view.*; import android.widget.*; public class MainActivity extends Activity { TextView status; static { try { System.loadLibrary("transcribe"); } catch(Throwable t){} } public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this); l.setOrientation(LinearLayout.VERTICAL); l.setPadding(32,48,32,32); TextView title=new TextView(this); title.setText("Parakeet Transcriber"); title.setTextSize(26); l.addView(title); Button pick=new Button(this); pick.setText("Choose Parakeet GGUF model"); l.addView(pick); status=new TextView(this); status.setText("Select the .gguf model from phone storage."); status.setTextSize(16); l.addView(status); pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.setType("application/octet-stream"); i.addCategory(Intent.CATEGORY_OPENABLE); startActivityForResult(i,7);}); setContentView(l);} protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d); if(r==7&&c==RESULT_OK&&d!=null){Uri u=d.getData(); status.setText("Model selected:\n"+u.toString()+"\n\nVulkan native runtime loaded.");}}}
